CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY, github_id bigint NOT NULL UNIQUE, login text NOT NULL, avatar_url text NOT NULL DEFAULT '', role text NOT NULL DEFAULT 'member' CHECK(role IN ('member','editor','operator')), invited boolean NOT NULL DEFAULT false, validation_quota integer NOT NULL DEFAULT 0 CHECK(validation_quota>=0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invitations(github_id bigint PRIMARY KEY, role text NOT NULL CHECK(role IN('member','editor')), validation_quota integer NOT NULL CHECK(validation_quota>=0), invited_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), scopes text[] NOT NULL DEFAULT '{web}', expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE oauth_states(token_hash text PRIMARY KEY, verifier text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE cli_sessions(id uuid PRIMARY KEY, secret_hash text NOT NULL, user_code text NOT NULL, user_id uuid REFERENCES users(id), expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE TABLE candidates(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), digest text NOT NULL, document jsonb NOT NULL, status text NOT NULL DEFAULT 'resolving_sources', findings jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,digest));
CREATE TABLE challenges(id uuid PRIMARY KEY, slug text NOT NULL UNIQUE, owner_id uuid NOT NULL REFERENCES users(id), candidate_id uuid NOT NULL REFERENCES candidates(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE challenge_versions(id uuid PRIMARY KEY, challenge_id uuid NOT NULL REFERENCES challenges(id), repository text NOT NULL, repository_id bigint NOT NULL, source_commit text NOT NULL CHECK(source_commit ~ '^[a-f0-9]{40}$'), source_digest text NOT NULL, manifest jsonb NOT NULL, status text NOT NULL DEFAULT 'draft', review_status text NOT NULL DEFAULT 'pending', intake_status text NOT NULL DEFAULT 'unavailable', badges text[] NOT NULL DEFAULT '{}', lock_digest text UNIQUE, deadline timestamptz NOT NULL, economic_mode text NOT NULL DEFAULT 'none' CHECK(economic_mode='none'), next_sequence bigint NOT NULL DEFAULT 0, watermark bigint NOT NULL DEFAULT 0 CHECK(watermark<=next_sequence), verified_best_id uuid, public_frontier_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX challenge_one_open_version ON challenge_versions(challenge_id) WHERE intake_status='open';
CREATE TABLE preflights(id uuid PRIMARY KEY, version_id uuid NOT NULL REFERENCES challenge_versions(id), status text NOT NULL DEFAULT 'queued', findings jsonb NOT NULL DEFAULT '[]', reports jsonb NOT NULL DEFAULT '[]', machine_receipt_digest text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE review_runs(id uuid PRIMARY KEY, version_id uuid NOT NULL REFERENCES challenge_versions(id), kind text NOT NULL, status text NOT NULL, report jsonb NOT NULL, digest text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE locks(digest text PRIMARY KEY, version_id uuid NOT NULL UNIQUE REFERENCES challenge_versions(id), document jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE artifacts(digest text PRIMARY KEY, blob_digest text NOT NULL, size bigint NOT NULL CHECK(size>=0), media_type text NOT NULL, owner_id uuid REFERENCES users(id), public_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE submission_intents(id uuid PRIMARY KEY, version_id uuid NOT NULL REFERENCES challenge_versions(id), owner_id uuid NOT NULL REFERENCES users(id), repository text NOT NULL, ref text NOT NULL, repository_id bigint, source_commit text, artifact_digest text REFERENCES artifacts(digest), disk_digest text REFERENCES artifacts(digest), status text NOT NULL DEFAULT 'github_fetch', request jsonb NOT NULL, findings jsonb NOT NULL DEFAULT '[]', submission_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE validation_grants(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), version_id uuid NOT NULL REFERENCES challenge_versions(id), artifact_digest text NOT NULL, resource_class text NOT NULL, units integer NOT NULL CHECK(units=2), status text NOT NULL CHECK(status IN('available','reserved','consumed','released')), UNIQUE(owner_id,version_id,artifact_digest));
CREATE TABLE submissions(id uuid PRIMARY KEY, version_id uuid NOT NULL REFERENCES challenge_versions(id), owner_id uuid NOT NULL REFERENCES users(id), intent_id uuid NOT NULL UNIQUE REFERENCES submission_intents(id), artifact_digest text NOT NULL REFERENCES artifacts(digest), disk_digest text NOT NULL REFERENCES artifacts(digest), sequence bigint NOT NULL, status text NOT NULL DEFAULT 'accepted', outcome text NOT NULL DEFAULT 'pending', score_ticks numeric(150,0), public boolean NOT NULL DEFAULT false, publish_requested boolean NOT NULL DEFAULT false, attribution jsonb NOT NULL DEFAULT '{}', receipt_digest text NOT NULL UNIQUE, adjudication_digest text, commitment text NOT NULL, commitment_salt text NOT NULL, grant_id uuid NOT NULL UNIQUE REFERENCES validation_grants(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(version_id,sequence), UNIQUE(version_id,artifact_digest));
ALTER TABLE challenge_versions ADD CONSTRAINT best_submission_fk FOREIGN KEY(verified_best_id) REFERENCES submissions(id);
ALTER TABLE challenge_versions ADD CONSTRAINT frontier_submission_fk FOREIGN KEY(public_frontier_id) REFERENCES submissions(id);
ALTER TABLE submission_intents ADD CONSTRAINT intent_submission_fk FOREIGN KEY(submission_id) REFERENCES submissions(id);
CREATE TABLE milestone_tiers(id text PRIMARY KEY, version_id uuid NOT NULL REFERENCES challenge_versions(id), title text NOT NULL, threshold_ticks numeric(150,0) NOT NULL);
CREATE TABLE milestone_claims(id uuid PRIMARY KEY, milestone_id text NOT NULL UNIQUE REFERENCES milestone_tiers(id), submission_id uuid NOT NULL REFERENCES submissions(id), receipt_digest text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE receipts(digest text PRIMARY KEY, payload jsonb NOT NULL, envelope jsonb, owner_id uuid REFERENCES users(id), public boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE capacity(id integer PRIMARY KEY CHECK(id=1), maximum_units integer NOT NULL CHECK(maximum_units>=0), reserved_units integer NOT NULL DEFAULT 0 CHECK(reserved_units>=0 AND reserved_units<=maximum_units));
INSERT INTO capacity(id,maximum_units) VALUES(1,0);
CREATE TABLE capacity_reservations(submission_id uuid PRIMARY KEY REFERENCES submissions(id), units integer NOT NULL DEFAULT 2, released_at timestamptz, fence bigint GENERATED ALWAYS AS IDENTITY);
CREATE TABLE runner_hosts(id text PRIMARY KEY, host_group text NOT NULL, public_key text NOT NULL, certificate_fingerprint text NOT NULL UNIQUE, enabled boolean NOT NULL DEFAULT false, last_seen_at timestamptz);
CREATE TABLE runner_jobs(id uuid PRIMARY KEY, purpose text NOT NULL, version_id uuid NOT NULL REFERENCES challenge_versions(id), submission_id uuid REFERENCES submissions(id), preflight_id uuid REFERENCES preflights(id), payload jsonb NOT NULL, envelope jsonb, status text NOT NULL DEFAULT 'queued', host_id text REFERENCES runner_hosts(id), excluded_group text, result_token_hash text, fence bigint NOT NULL DEFAULT 1, lease_expires_at timestamptz, attempts integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE runner_results(job_id uuid PRIMARY KEY REFERENCES runner_jobs(id), host_id text NOT NULL REFERENCES runner_hosts(id), digest text NOT NULL UNIQUE, envelope jsonb NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE jobs(id uuid PRIMARY KEY, kind text NOT NULL, resource_id text NOT NULL, status text NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), lease_expires_at timestamptz, lease_token text, last_error text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(kind,resource_id));
CREATE INDEX jobs_ready ON jobs(available_at) WHERE status IN('queued','retry');
CREATE TABLE outbox_events(id uuid PRIMARY KEY, kind text NOT NULL, resource_id text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz);
CREATE TABLE audit_events(sequence bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, version_id uuid REFERENCES challenge_versions(id), kind text NOT NULL, payload jsonb NOT NULL, previous_digest text NOT NULL, digest text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE flags(id uuid PRIMARY KEY, version_id uuid NOT NULL REFERENCES challenge_versions(id), owner_id uuid NOT NULL REFERENCES users(id), category text NOT NULL, message text NOT NULL, evidence_url text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE editorial_decisions(id uuid PRIMARY KEY, version_id uuid NOT NULL REFERENCES challenge_versions(id), editor_id uuid NOT NULL REFERENCES users(id), action text NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency(user_id uuid NOT NULL REFERENCES users(id), key text NOT NULL, request_hash text NOT NULL, response jsonb, status_code integer, expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', PRIMARY KEY(user_id,key));
CREATE TABLE webhook_deliveries(id text PRIMARY KEY, event text NOT NULL, received_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION protect_locked_version() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.lock_digest IS NOT NULL AND (NEW.manifest IS DISTINCT FROM OLD.manifest OR NEW.source_commit IS DISTINCT FROM OLD.source_commit OR NEW.source_digest IS DISTINCT FROM OLD.source_digest OR NEW.deadline IS DISTINCT FROM OLD.deadline OR NEW.lock_digest IS DISTINCT FROM OLD.lock_digest OR NEW.economic_mode IS DISTINCT FROM OLD.economic_mode) THEN RAISE EXCEPTION 'locked challenge contract is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_locked_version BEFORE UPDATE ON challenge_versions FOR EACH ROW EXECUTE FUNCTION protect_locked_version();
CREATE FUNCTION deny_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'append-only audit history'; END $$;
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION deny_audit_mutation();
CREATE TRIGGER immutable_claim BEFORE UPDATE OR DELETE ON milestone_claims FOR EACH ROW EXECUTE FUNCTION deny_audit_mutation();
